package io.github.diodeme.ji.agent.core;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.ai.CancellationToken;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.extension.ToolInterceptor;
import io.github.diodeme.ji.extension.ToolRetryContract;
import io.github.diodeme.ji.extension.WorkspaceProvider;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class ToolBatchSchedulerTest {
    private static final Instant NOW = Instant.parse("2026-09-04T00:00:00Z");
    private static final Clock CLOCK = Clock.fixed(NOW, ZoneOffset.UTC);
    private static final WorkspaceProvider.WorkspaceIdentity WORKSPACE =
            new WorkspaceProvider.WorkspaceIdentity("workspace-1", 0);

    @Test
    void completesAllPreflightInOrderBeforeStartingEffects() {
        var order = java.util.Collections.synchronizedList(new ArrayList<String>());
        ToolExecutionPolicy policy = context -> {
            order.add("preflight-" + context.toolCallId());
            return ToolExecutionPolicy.Evaluation.allow(false, "allow");
        };
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = scheduler(policy, executor, 8, 32, 10)) {
            var result = scheduler.execute(List.of(
                    request("session-1", "one", false, () -> { order.add("effect-one"); return "one"; }),
                    request("session-1", "two", false, () -> { order.add("effect-two"); return "two"; })),
                    CancellationToken.NONE).toCompletableFuture().join();
            assertEquals(List.of("preflight-one", "preflight-two"), order.subList(0, 2));
            assertFalse(result.sequential());
            assertEquals(List.of("one", "two"), result.items().stream().map(ToolBatchScheduler.ItemResult::value).toList());
        }
    }

    @Test
    void oneSequentialToolSerializesTheWholeBatch() {
        AtomicInteger running = new AtomicInteger();
        AtomicInteger maximum = new AtomicInteger();
        ToolExecutionPolicy policy = context -> ToolExecutionPolicy.Evaluation.allow(
                "two".equals(context.toolCallId()), "rule");
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = scheduler(policy, executor, 8, 32, 10)) {
            var requests = List.of(
                    request("session-1", "one", false, () -> observed(running, maximum)),
                    request("session-1", "two", true, () -> observed(running, maximum)),
                    request("session-1", "three", false, () -> observed(running, maximum)));
            var result = scheduler.execute(requests, CancellationToken.NONE).toCompletableFuture().join();
            assertTrue(result.sequential());
            assertEquals(1, maximum.get());
        }
    }

    @Test
    void enforcesSessionAndHostLimitsByQueueingEffects() throws Exception {
        CountDownLatch release = new CountDownLatch(1);
        AtomicInteger sessionOne = new AtomicInteger();
        AtomicInteger sessionTwo = new AtomicInteger();
        AtomicInteger maxSessionOne = new AtomicInteger();
        AtomicInteger maxHost = new AtomicInteger();
        AtomicInteger host = new AtomicInteger();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = scheduler(context -> ToolExecutionPolicy.Evaluation.allow(false, "allow"),
                     executor, 2, 3, 20)) {
            List<ToolBatchScheduler.ToolRequest<Integer>> requests = new ArrayList<>();
            for (int index = 0; index < 4; index++) {
                String session = index < 3 ? "session-1" : "session-2";
                AtomicInteger own = index < 3 ? sessionOne : sessionTwo;
                AtomicInteger maximum = index < 3 ? maxSessionOne : new AtomicInteger();
                int item = index;
                requests.add(request(session, "tool-" + index, false, () -> {
                    int ownNow = own.incrementAndGet();
                    maximum.accumulateAndGet(ownNow, Math::max);
                    int hostNow = host.incrementAndGet();
                    maxHost.accumulateAndGet(hostNow, Math::max);
                    try { release.await(5, TimeUnit.SECONDS); } catch (InterruptedException e) { throw new RuntimeException(e); }
                    host.decrementAndGet(); own.decrementAndGet(); return item;
                }));
            }
            CompletableFuture<ToolBatchScheduler.BatchResult<Integer>> future = scheduler.execute(requests,
                    CancellationToken.NONE).toCompletableFuture();
            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
            while (scheduler.snapshot().hostActive() < 3 && System.nanoTime() < deadline) Thread.onSpinWait();
            assertEquals(3, scheduler.snapshot().hostActive());
            assertEquals(1, scheduler.snapshot().queued());
            release.countDown();
            assertEquals(4, future.get(5, TimeUnit.SECONDS).items().size());
            assertEquals(2, maxSessionOne.get());
            assertEquals(3, maxHost.get());
        }
    }

    @Test
    void rechecksPolicyAndOperationIdentityImmediatelyBeforeAndAfterEffect() {
        AtomicBoolean valid = new AtomicBoolean(true);
        AtomicInteger evaluation = new AtomicInteger();
        ToolExecutionPolicy policy = context -> evaluation.incrementAndGet() == 1
                ? ToolExecutionPolicy.Evaluation.allow(false, "initial")
                : ToolExecutionPolicy.Evaluation.deny("revoked");
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = scheduler(policy, executor, 8, 32, 10)) {
            var failure = assertThrows(java.util.concurrent.CompletionException.class, () -> scheduler.execute(
                    List.of(request("session-1", "one", false, valid::get, () -> "never")), CancellationToken.NONE)
                    .toCompletableFuture().join());
            assertEquals(ErrorCode.TOOL_POLICY_DENIED, ((JiException) failure.getCause()).error().code());
        }

        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = scheduler(context -> ToolExecutionPolicy.Evaluation.allow(false, "allow"),
                     executor, 8, 32, 10)) {
            var failure = assertThrows(java.util.concurrent.CompletionException.class, () -> scheduler.execute(
                    List.of(request("session-1", "one", false, valid::get, () -> {
                        valid.set(false); return "late";
                    })), CancellationToken.NONE).toCompletableFuture().join());
            assertEquals(ErrorCode.OPERATION_STALE_COMPLETION, ((JiException) failure.getCause()).error().code());
        }
    }

    @Test
    void permissionUsesExpiryRevisionAndCancellationContracts() {
        var permission = permission("permission-1", 3);
        PermissionDecider stale = (request, cancellation) -> CompletableFuture.completedFuture(
                new PermissionDecider.Decision(request.permissionId(), request.revision() + 1,
                        request.revision() + 2, PermissionDecider.Outcome.ALLOW, NOW));
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = new ToolBatchScheduler(context -> ToolExecutionPolicy.Evaluation.ask(false, "ask"),
                     stale, List.of(), executor, CLOCK, 8, 32, 10)) {
            var request = new ToolBatchScheduler.ToolRequest<>(context("session-1", "one"), "operation-one", 3,
                    permission, ToolRetryContract.READ_ONLY, null, () -> true, () -> "never");
            var failure = assertThrows(java.util.concurrent.CompletionException.class,
                    () -> scheduler.execute(List.of(request), CancellationToken.NONE).toCompletableFuture().join());
            assertEquals(ErrorCode.PERMISSION_REVISION_CONFLICT, ((JiException) failure.getCause()).error().code());
        }
        PermissionDecider.Request expired = new PermissionDecider.Request("permission-2", "host-1", "session-1",
                "actor-1", WORKSPACE, "one", "test", Map.of(), 0, NOW.minusSeconds(1_801), NOW.minusSeconds(1));
        var coordinator = new PermissionCoordinator((request, cancellation) -> CompletableFuture.completedFuture(
                PermissionDecider.Decision.allow(request, NOW)), CLOCK);
        var failure = assertThrows(java.util.concurrent.CompletionException.class,
                () -> coordinator.decide(expired, CancellationToken.NONE).join());
        assertEquals(ErrorCode.PERMISSION_EXPIRED, ((JiException) failure.getCause()).error().code());
    }

    @Test
    void retryContractFailsClosed() {
        var request = new ToolBatchScheduler.ToolRequest<>(context("session-1", "one"), "operation-one", 0,
                null, null, null, () -> true, () -> "ok");
        assertFalse(request.mayResume());
        var resumable = new ToolBatchScheduler.ToolRequest<>(context("session-1", "two"), "operation-two", 0,
                null, ToolRetryContract.RESUMABLE, "checkpoint", () -> true, () -> "ok");
        assertTrue(resumable.mayResume());
    }

    private static ToolBatchScheduler scheduler(ToolExecutionPolicy policy, java.util.concurrent.Executor executor,
                                                 int sessionLimit, int hostLimit, int queueLimit) {
        PermissionDecider allow = (request, cancellation) -> CompletableFuture.completedFuture(
                PermissionDecider.Decision.allow(request, NOW));
        return new ToolBatchScheduler(policy, allow, List.<ToolInterceptor>of(), executor, CLOCK,
                sessionLimit, hostLimit, queueLimit);
    }

    private static <T> ToolBatchScheduler.ToolRequest<T> request(String sessionId, String toolCallId,
                                                                  boolean ignored, java.util.function.Supplier<T> effect) {
        return request(sessionId, toolCallId, ignored, () -> true, effect);
    }

    private static <T> ToolBatchScheduler.ToolRequest<T> request(String sessionId, String toolCallId,
                                                                  boolean ignored, java.util.function.Supplier<Boolean> valid,
                                                                  java.util.function.Supplier<T> effect) {
        return new ToolBatchScheduler.ToolRequest<>(context(sessionId, toolCallId), "operation-" + toolCallId,
                0, null, ToolRetryContract.NON_RETRYABLE, null, valid, effect);
    }

    private static ToolExecutionPolicy.Context context(String sessionId, String toolCallId) {
        return new ToolExecutionPolicy.Context("host-1", sessionId, "actor-1", "test", WORKSPACE,
                toolCallId, "test", Map.of(), 0, NOW);
    }

    private static PermissionDecider.Request permission(String permissionId, long revision) {
        return new PermissionDecider.Request(permissionId, "host-1", "session-1", "actor-1", WORKSPACE,
                "one", "test", Map.of(), revision, NOW, NOW.plusSeconds(1_800));
    }

    private static int observed(AtomicInteger running, AtomicInteger maximum) {
        int value = running.incrementAndGet();
        maximum.accumulateAndGet(value, Math::max);
        running.decrementAndGet();
        return value;
    }
}
